/**
 * @method
 * @name scwin.tx_fn_Transform
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Transform = async function () {
    const sbmOptions = {
        id: "tx_fn_Transform",
        method: "post",
        action: "/filing/fssForm.do",
        ref: "dma_TransformReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50104.tx_fn_Transform" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.transform
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.transform = async function () {
    /* sdd-asis-lifecycle:begin fn_Transform — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!scwin.validate()) {
        return;
    }
    const _url = "about:blank";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=680,height=700";
    const popWin = $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), String((typeof _props !== 'undefined' ? _props : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "fssFormPop", scrollbars: true, resizable: true, width: "680", height: "700", type: "pageFramePopup" }, { id: '' }) : { id: "fssFormPop", scrollbars: true, resizable: true, width: "680", height: "700", type: "pageFramePopup" }), {});
    $c.util.getComponent('dma_TransformReq').set('method', "viewFssForm");
    scwin.form_fssForm.action = "/filing/document.fssForm.do";
    scwin.form_fssForm.target = "fssFormPop";
    await scwin.tx_fn_Transform();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 09. 29
