*/
scwin.validate = async function () {
    if (String(($c.util.getComponent("upd_templateFile") || { getValue: function () { return ''; } }).getValue() || '').replace(/\s/g, '') === '') { await $c.win.alert("서식파일을 입력해 주세요."); ($c.util.getComponent("upd_templateFile") && $c.util.getComponent("upd_templateFile").setFocus ? $c.util.getComponent("upd_templateFile").setFocus() : ($c.util.getComponent("upd_templateFile") && $c.util.getComponent("upd_templateFile").focus ? $c.util.getComponent("upd_templateFile").focus() : void 0)); return false; }
    return true;
};


/**
